export const normalizeRole = (r) => ROLE_ALIASES[r] || r || 'agent';
export const ADMIN_ROLE_SET = new Set(['owner', 'broker', 'office_admin']);
export const isAdminRole = (r) => ADMIN_ROLE_SET.has(normalizeRole(r)) || r === 'super_admin';

/** Does this profile have the permission? Per-user overrides win over role defaults. */
export function can(profile, key) {
  if (!profile) return false;
  if (profile.role === 'super_admin') return true;
  const o = profile.permissions || {};
  if (Object.prototype.hasOwnProperty.call(o, key)) return !!o[key];
  return (PERMS[key]?.roles || []).includes(normalizeRole(profile.role));
}
